export interface ACProduct {
  id: string;
  type: ACType;
  brand: Brand;
  inverter: InverterType;
  tonnage: string;
  starRating: string;
  modelNumber: string;
  price: number;
  mrp?: number; // Maximum Retail Price
  features: string[];
  image: string; // Main image (for backward compatibility)
  images: string[]; // Array of images for product gallery
  description: string;
  coolingCapacity?: string; // CC in watts
  indoorUnitDimensions?: string; // IDU dimensions
  outdoorUnitDimensions?: string; // ODU dimensions
  productUrl?: string; // Product specification URL
  gasType?: string; // R32, R410A etc
  specialFeatures?: string[]; // Additional special features like Streamer Discharge
}

export type ACType =
  | "split"
  | "window"
  | "cassette"
  | "multi-split"
  | "one-way-cassette";
export type Brand =
  | "o-general"
  | "mitsubishi-heavy"
  | "mitsubishi-electric"
  | "mitsubishi-akabishi"
  | "daikin"
  | "panasonic"
  | "blue-star"
  | "carrier"
  | "hitachi"
  | "lg"
  | "voltas"
  | "hisense"
  | "godrej"
  | "lloyd"
  | "vestar"
  | "haier"
  | "bpl"
  | "IFB";
export type InverterType = "inverter" | "non-inverter";

